# Casa de la Cana super (C5b, contract 48), 9 x 7, interior. column = i, row = j. A fisherman's house on Ruta 16: he gives the CANA SUPER (`cana_aleacion`, flag 833) the first
# time you talk to him (a full bag keeps the flag clear and he gives it at the next talk). Same wooden floor as the Cana buena house; its own touch: a lifebuoy on the wall and the catch of the day (lobster traps).
@map casa_cana_super
@size 9 7
@interior yes
@bg 3
@fill floor_wood
@spawn door 4 5 N
@flag cana_super_given 833
@legend
  .  tile=floor_wood
  a  tile=none object=wall_corner
  b  tile=none object=wall_j
  c  tile=none object=wall_win_j
  d  tile=none object=wall_i
  e  object=bed
  f  object=bookshelf text=casa.books interact=look
  h  object=table
  i  npc=pescador_s id=fisher face=SE script=fisher
  j  object=trap
  l  object=lifebuoy
  k  tile=mat
@grid
  abbcbbcbb
  de.fl.jj.
  de.......
  d..hi....
  d........
  d..j.....
  d...kk...
@warp k -> ruta_16 spawn=cana_door
# The fisherman: the CANA SUPER at the first talk, then a last line.
@script fisher npc
    npc_face_hero fisher
    jf cana_super_given said
    say cana2.a
    call fisher_gift
    end
  said:
    say cana2.after
@end
@script fisher_gift called
    say cana2.b
    give_item cana_aleacion 1
    jv 0 0 full
    item_var 0 cana_aleacion
    say gl.gift
    setf cana_super_given
    say cana2.about
    end
  full:
    say gl.found.full
@end
